package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
)

// ThresholdsFile 是按仓库低库存阈值配置相对仓库根的位置。
const ThresholdsFile = "config/thresholds.json"

// thresholdsFile 覆盖默认配置路径；测试把它指向临时文件，生产保持为空。
var thresholdsFile string

// loadThresholds 每次调用都重新读取配置文件，所以运维改完保存即生效，
// 不需要重新构建或重启进程。
//
// 读不到文件、或内容不是合法的「仓库名 → 阈值」JSON 对象时返回空配置，
// 让每个仓库回退到 DefaultLowStockThreshold。
func loadThresholds() map[string]int {
	path := thresholdsFile
	if path == "" {
		path = findThresholdsFile()
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// thresholdFor 返回仓库配的阈值；没配就回退到 DefaultLowStockThreshold。
func thresholdFor(thresholds map[string]int, warehouse string) int {
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// findThresholdsFile 从当前目录逐级向上找 config/thresholds.json，
// 这样从仓库根启动、或 go test 在 inventory/ 下运行时读到的是同一份配置。
func findThresholdsFile() string {
	dir, err := os.Getwd()
	if err != nil {
		return ThresholdsFile
	}
	for {
		candidate := filepath.Join(dir, ThresholdsFile)
		if _, err := os.Stat(candidate); err == nil {
			return candidate
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ThresholdsFile
		}
		dir = parent
	}
}

