package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// withThresholdsFile 把配置指向一个临时文件，测试结束自动还原。
func withThresholdsFile(t *testing.T, content string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
	useThresholdsPath(t, path)
	return path
}

// useThresholdsPath 临时覆盖配置路径，测试结束还原为默认解析。
func useThresholdsPath(t *testing.T, path string) {
	t.Helper()
	original := thresholdsFile
	thresholdsFile = path
	t.Cleanup(func() { thresholdsFile = original })
}

func TestConfiguredWarehouseUsesConfiguredThreshold(t *testing.T) {
	withThresholdsFile(t, `{"xian": 20}`)
	if got := LowStockThreshold("xian"); got != 20 {
		t.Fatalf("LowStockThreshold(xian) = %d, 期望 20", got)
	}
}

func TestConfiguredWarehouseAffectsIsLowStock(t *testing.T) {
	withThresholdsFile(t, `{"xian": 20}`)
	if !IsLowStock("xian", 19) {
		t.Fatal("19 < 20，应当算低库存")
	}
	if IsLowStock("xian", 20) {
		t.Fatal("等于阈值不算低库存（严格小于）")
	}
}

func TestEditingConfigTakesEffectWithoutRebuild(t *testing.T) {
	path := withThresholdsFile(t, `{"xian": 10}`)
	if got := LowStockThreshold("xian"); got != 10 {
		t.Fatalf("首次读取 = %d, 期望 10", got)
	}
	// 直接改文件、不重建，下一次调用就应当读到新值。
	if err := os.WriteFile(path, []byte(`{"xian": 30}`), 0o600); err != nil {
		t.Fatal(err)
	}
	if got := LowStockThreshold("xian"); got != 30 {
		t.Fatalf("改配置后 = %d, 期望 30（改文件应当立即生效）", got)
	}
}

func TestMissingConfigFallsBackToDefault(t *testing.T) {
	useThresholdsPath(t, filepath.Join(t.TempDir(), "missing.json"))
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("配置缺失时应回退默认值 %d, 得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestMalformedConfigFallsBackToDefault(t *testing.T) {
	withThresholdsFile(t, `{not json`)
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("配置损坏时应回退默认值 %d, 得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestLowStockWarehousesUsesPerWarehouseThresholds(t *testing.T) {
	withThresholdsFile(t, `{"shanghai": 10}`)
	// shanghai: 9 < 10 低；chengdu 未配置，4 < 默认 5 低。
	got := LowStockWarehouses(map[string]int{"shanghai": 9, "chengdu": 4, "wuhan": 5})
	want := []string{"chengdu", "shanghai"}
	if len(got) != len(want) || got[0] != want[0] || got[1] != want[1] {
		t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
	}
}

